<?php
/** TEMP PS S1620 run e10d — D: darbalaukis v3.35.1 → v3.35.2 (dalis 2/2 + sargai + ping-atkūrimas + eilės prieš) · Q: versija, eilės po. */
add_action('init', function(){
  if (!isset($_GET['ps_e10d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e10d'])); $o=array('v'=>'S1620 e10d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  $tu=get_user_by('login','testuotojas'); $uid=$tu->ID; $exp=time()+900; $tok=WP_Session_Tokens::get_instance($uid)->create($exp);
  $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'logged_in',$tok))));
  $G=function($u) use($cs){ return wp_remote_get($u,array('cookies'=>$cs,'timeout'=>90,'sslverify'=>false,'redirection'=>0)); };
  $eiles=function() use($G){ $r=$G(admin_url('admin.php?page=ps-desk&eile=nauji')); $h=(string)wp_remote_retrieve_body($r); return array('code'=>wp_remote_retrieve_response_code($r),'nav'=>mb_substr(trim(preg_replace('/\s+/',' ',wp_strip_all_tags(preg_match('/<main class="dl-main">(.*?)<div class="dl-kortele/su',$h,$mm)?$mm[1]:''))),0,140),'pilnas_pav'=>(int)preg_match('/Animonda Carny Adult Beef \+ Chicken \+ Duck[^<…]{3,}/u',$h),'css_naujas'=>(int)(strpos($h,'.dl a.dl-e-naujas{')!==false)); };
  $ping=function(){ $r=wp_remote_get(admin_url('admin-ajax.php?action=heartbeat'),array('timeout'=>90,'sslverify'=>false)); $b=(string)wp_remote_retrieve_body($r); return array('code'=>wp_remote_retrieve_response_code($r),'fatal'=>(int)(stripos($b,'Fatal error')!==false||stripos($b,'Parse error')!==false),'err'=>is_wp_error($r)?$r->get_error_message():''); };
  try{
  if($f==='D'){
    $o['eiles_pries']=$eiles();
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $p1=(string)@file_get_contents($bk.'/dl-v3352.part1'); if(md5($p1)!=='5742882eaedb1a251468767f94a9b18a'){ $o['STOP']='part1 md5 '.md5($p1); $J($o); }
    $c2='';
    $gz=base64_decode($p1.$c2,true); $code=$gz===false?false:gzdecode($gz); if($code===false){ $o['STOP']='b64/gz'; $J($o); }
    $o['bytes']=strlen($code); $o['md5']=md5($code); if($o['md5']!=='cc27c448df44786340da7066ee01b7bc'){ $o['STOP']='md5'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=md5_file($t); $o['klase_pries']=class_exists('Petshop_Darbalaukis')?Petshop_Darbalaukis::VERSIJA:0;
    if($o['buvo']!=='4e8c13665454cb6d7413ba8892bf4b6a'){ $o['STOP']='gyvas nežinomas ('.$o['buvo'].')'; $J($o); }
    $bkf=$bk.'/petshop-darbalaukis-v3351-BACKUP-'.date('Y-m-d').'.php'; $o['backup']=copy($t,$bkf);
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); @unlink($bk.'/dl-v3352.part1'); if(function_exists('opcache_invalidate')){ @opcache_invalidate($t,true); }
    $o['ping']=$ping(); if($o['ping']['fatal']||$o['ping']['code']>=500||$o['ping']['err']){ copy($bkf,$t); $o['ATKURTA']='darbalaukis atkurtas v3.35.1'; $o['po_atkurimo']=md5_file($t); $J($o); }
    $J($o);
  }
  if($f==='Q'){ $o['versija']=class_exists('Petshop_Darbalaukis')?Petshop_Darbalaukis::VERSIJA:'NĖRA'; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'); $o['eiles_po']=$eiles(); $o['ping']=$ping(); $o['temp_liko']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}snippets WHERE name LIKE 'TEMP%'"); $J($o); }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.basename($e->getFile()).':'.$e->getLine(); }
  $J($o);
},99);
